/*
 * rip/test/test_rip_data.c - the RIP module data blocks (source-thww)
 *
 * Generated by: Claude Opus 5.5
 *
 * rip/rip_data.c is #included, so the objects under test are the real
 * blocks with the image's contents:
 *
 *   RIP_$WIRED_DATA    map "D E26258 RIP_WIRED size = C8C"
 *   RIP_$INIT_DATA     map "D E3502C RIP_WIRED size = 4"
 *   RIP_$RTWIRED_DATA  map "D E87D68 RIP_RTWIRED size = 18"
 *
 * Checked: image addresses and sizes, the offsets that hold on every build
 * (RIP_$WIRED_DATA's cells behind its exclusion locks are asserted at
 * compile time on the target only), the table shapes and the initial
 * contents.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "rip/rip_internal.h"
#include "../rip_data.c"

#define OFF(block, field) \
    ((size_t)((const uint8_t *)&(field) - (const uint8_t *)&(block)))

/* ==========================================================================
 * Tests
 * ========================================================================== */

TEST(block_addresses_and_sizes)
{
    ASSERT_EQ(0x00E26258u, MODULE_DATA_ADDR(RIP_$WIRED_DATA));
    ASSERT_EQ(0x00E3502Cu, MODULE_DATA_ADDR(RIP_$INIT_DATA));
    ASSERT_EQ(0x00E87D68u, MODULE_DATA_ADDR(RIP_$RTWIRED_DATA));
    ASSERT_EQ(0xC8C, RIP_$WIRED_DATA_SIZE);
    ASSERT_EQ(RIP_$INIT_DATA_SIZE, sizeof(RIP_$INIT_DATA));
    ASSERT_EQ(RIP_$RTWIRED_DATA_SIZE, sizeof(RIP_$RTWIRED_DATA));
    /* RIP_RTWIRED ends where ROUTE_RTWIRED begins */
    ASSERT_EQ(0x00E87D80u,
              MODULE_DATA_ADDR(RIP_$RTWIRED_DATA) + RIP_$RTWIRED_DATA_SIZE);
    /* RIP_WIRED ends where ROUTE_WIRED begins */
    ASSERT_EQ(0x00E26EE4u,
              MODULE_DATA_ADDR(RIP_$WIRED_DATA) + RIP_$WIRED_DATA_SIZE);
}

TEST(wired_offsets_before_the_locks)
{
    ASSERT_EQ(0x000, OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.route_port));
    ASSERT_EQ(0x010, OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.xns_error_mutex));
    ASSERT_EQ(RIP_TABLE_SIZE,
              sizeof(RIP_$WIRED_DATA.info) / sizeof(RIP_$WIRED_DATA.info[0]));
    ASSERT_EQ(RIP_TABLE_SIZE,
              sizeof(RIP_$WIRED_DATA.stats.net_pkts) /
                  sizeof(RIP_$WIRED_DATA.stats.net_pkts[0]));
    /* the tail cells follow each other as in the map */
    ASSERT_EQ(2, OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.ns_announcement) -
                 OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.std_idp_channel));
    ASSERT_EQ(2, OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.bcast_control) -
                 OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.ns_announcement));
    ASSERT_EQ(0x1E, OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.std_recent_changes) -
                    OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.bcast_control));
    ASSERT_EQ(2, OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.recent_changes) -
                 OFF(RIP_$WIRED_DATA, RIP_$WIRED_DATA.std_recent_changes));
}

TEST(stats_record)
{
    /* rip_$stats_t is packed: its layout holds on every build */
    ASSERT_EQ(0x110, sizeof(rip_$stats_t));
    ASSERT_EQ(0x0C, OFF(RIP_$WIRED_DATA.stats, RIP_$WIRED_DATA.stats.local_net_pkts));
    ASSERT_EQ(0x10, OFF(RIP_$WIRED_DATA.stats, RIP_$WIRED_DATA.stats.net_pkts));
}

TEST(wired_initial_contents)
{
    static const uint8_t bcast[30] = {
        0x00, 0x90, 0x00, 0x02, 0x00, 0x01, 0x00, 0x01,
        0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0x00, 0x00,
    };
    int i;

    ASSERT_EQ(0, RIP_$WIRED_DATA.route_port);
    ASSERT_EQ(1, RIP_$WIRED_DATA.stats._reserved0);         /* 0x00E262AC */
    ASSERT_EQ(0, RIP_$WIRED_DATA.stats.packets_received);
    ASSERT_EQ(-1, RIP_$WIRED_DATA.std_idp_channel);         /* 0x00E26EBC */
    ASSERT_EQ(0x00, RIP_$WIRED_DATA.ns_announcement[0]);    /* 0x00E26EBE */
    ASSERT_EQ(0x03, RIP_$WIRED_DATA.ns_announcement[1]);
    for (i = 0; i < 30; i++) {
        ASSERT_EQ(bcast[i], RIP_$WIRED_DATA.bcast_control[i]);
    }
    ASSERT_EQ(0, RIP_$WIRED_DATA.std_recent_changes);
    ASSERT_EQ(0, RIP_$WIRED_DATA.recent_changes);
    for (i = 0; i < RIP_TABLE_SIZE; i++) {
        ASSERT_EQ(0, RIP_$WIRED_DATA.info[i].network);
        ASSERT_EQ(0, RIP_$WIRED_DATA.stats.net_pkts[i]);
    }
}

TEST(init_data)
{
    ASSERT_EQ(0x00, OFF(RIP_$INIT_DATA, RIP_$INIT_DATA.request));
    ASSERT_EQ(0, RIP_$INIT_DATA.request);
    ASSERT_EQ(0, RIP_$INIT_DATA._02);
}

TEST(rtwired_offsets_and_contents)
{
    static const uint8_t halt[8] = { 0x00, 0x02, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x10 };
    const uint8_t *p = (const uint8_t *)&RIP_$RTWIRED_DATA;
    int i;

    ASSERT_EQ(0x00, OFF(RIP_$RTWIRED_DATA, RIP_$RTWIRED_DATA.dest_addr));
    ASSERT_EQ(0x0C, OFF(RIP_$RTWIRED_DATA, RIP_$RTWIRED_DATA.send_flags));
    ASSERT_EQ(0x10, OFF(RIP_$RTWIRED_DATA, RIP_$RTWIRED_DATA.halt_data));
    /* 0x00E87D68: 16 zero bytes, then the halt packet data */
    for (i = 0; i < 0x10; i++) {
        ASSERT_EQ(0, p[i]);
    }
    for (i = 0; i < 8; i++) {
        ASSERT_EQ(halt[i], p[0x10 + i]);
    }
}

int main(void)
{
    printf("RIP module data tests\n");
    RUN_TEST(block_addresses_and_sizes);
    RUN_TEST(wired_offsets_before_the_locks);
    RUN_TEST(stats_record);
    RUN_TEST(wired_initial_contents);
    RUN_TEST(init_data);
    RUN_TEST(rtwired_offsets_and_contents);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
